insert into public.page_content (page, section, data) values ('about', 'main', '{"heading":"Engineer by trade, analyst by habit.","lead":"I am Emmanuel Olowu, a senior full-stack product engineer based in Lagos. I build software end to end and stay with it after launch.","story":"I started out building websites for small businesses, which taught me early that software only matters if it moves something for the person paying for it.\n\nSince then I have worked across the stack and across industries: commerce, fintech, logistics and media. I am as comfortable designing a Postgres schema as I am tuning an animation, and I pick tools for the problem rather than the other way round.\n\nAlongside engineering I am studying Information Technology and Business Information Systems at Middlesex University London. It shapes how I work: I want to know the business question before writing the first line, and I want the data to prove the answer.","image":{"src":"https://images.unsplash.com/photo-1522529599102-193c0d76b5b6","width":5472,"height":3648,"alt":"Emmanuel smiling outdoors","credit":"Unsplash"},"facts":[{"label":"Based in","value":"Lagos, working worldwide"},{"label":"Focus","value":"Product, platforms, data"},{"label":"Studying","value":"BSc (Hons) IT & BIS, Middlesex University London"},{"label":"Building since","value":"2019"}],"principles":[{"title":"Start with the question","body":"Every build begins with what the business needs to learn or earn. Features follow."},{"title":"Boring where it counts","body":"Money, auth and data get proven tools. Novelty goes where users can feel it."},{"title":"Ship, then measure","body":"Small releases, real usage numbers, and changes based on what people actually do."},{"title":"Leave it better documented","body":"The next engineer, or the next me, should not need to guess."}]}'::jsonb);
