insert into public.projects (slug, title, summary, role, client, year, tags, stack, links, metrics, cover, gallery, body, featured, published, sort_order) values ('folio-builder', 'Folio Builder', 'A CMS that lets photographers, designers and studios publish a fast portfolio site without hiring a developer.', 'Founder and lead engineer', 'Own product', 2025, array['Product', 'SaaS']::text[], array['TypeScript', 'React', 'TanStack Start', 'PostgreSQL', 'Cloudinary']::text[], '[{"label":"Source","url":"https://github.com/zeddyemy/Folio-Builder"}]'::jsonb, '[{"value":"< 10 min","label":"from sign-up to a live site"},{"value":"95+","label":"Lighthouse performance on published sites"}]'::jsonb, '{"src":"https://images.unsplash.com/photo-1600132806370-bf17e65e942f","width":3865,"height":2257,"alt":"Wireframe sketches of a web interface","credit":"Unsplash"}'::jsonb, '[{"src":"https://images.unsplash.com/photo-1587440871875-191322ee64b0","width":4229,"height":2819,"alt":"A team sketching wireframes with sticky notes","credit":"Unsplash"},{"src":"https://images.unsplash.com/photo-1499951360447-b19be8fe80f5","width":5848,"height":3899,"alt":"A bright desk with a laptop and monitor","credit":"Unsplash"}]'::jsonb, '## The problem

Creative people kept asking me for the same thing: a portfolio that looks considered, loads fast on a phone, and can be updated without calling a developer. Website builders were either slow, generic, or both.

## What I built

Folio Builder is a multi-tenant CMS with a small set of opinionated templates. Owners upload work, reorder it with drag and drop, and edit every line of copy in place. Images go straight to a CDN with responsive sizes generated on the fly.

- Tenant-aware data model with row-level security, so one database serves every site safely
- Direct browser uploads with signed requests, keeping large files off the app server
- Server-rendered pages cached at the edge, so a published site stays fast without extra work

## Decisions worth noting

I kept the template count deliberately low. Every extra template multiplies testing and support, and most users want a good default more than they want choice.

```ts
// Every query is scoped by tenant before it reaches the database
const projects = await db.from(''projects'').select(''*'').eq(''site_id'', site.id).eq(''published'', true)
```

## Where it is now

The product runs my own client sites and is being prepared for a small public beta.', true, true, 1);
insert into public.projects (slug, title, summary, role, client, year, tags, stack, links, metrics, cover, gallery, body, featured, published, sort_order) values ('storezed', 'StoreZed', 'A commerce platform with a built-in wallet, so merchants can take payments, hold balances and pay out in one place.', 'Lead backend engineer', 'StoreZed', 2023, array['Fintech', 'Commerce']::text[], array['Python', 'Flask', 'PostgreSQL', 'Redis', 'Paystack']::text[], '[{"label":"Source","url":"https://github.com/zeddyemy/StoreZed"}]'::jsonb, '[{"value":"0","label":"balance mismatches after the ledger rewrite"},{"value":"3x","label":"faster checkout API after caching"}]'::jsonb, '{"src":"https://images.unsplash.com/photo-1551650975-87deedd944c3","width":4843,"height":3632,"alt":"Hand holding a phone with a finance app","credit":"Unsplash"}'::jsonb, '[{"src":"https://images.unsplash.com/photo-1556742049-0cfed4f6a45d","width":3000,"height":2002,"alt":"A customer paying at a shop counter","credit":"Unsplash"},{"src":"https://images.unsplash.com/photo-1563986768609-322da13575f3","width":6720,"height":4480,"alt":"Testing a web app on a laptop and a phone","credit":"Unsplash"}]'::jsonb, '## The problem

Merchants were reconciling sales against payouts by hand. Balances drifted because the wallet was a single number on a user row, updated from several places.

## What I built

I replaced the balance column with a double-entry ledger. Every movement of money is two rows that must sum to zero, and a wallet balance is simply a query over those rows.

```python
def transfer(debit: Account, credit: Account, amount: Decimal, ref: str) -> None:
    with db.transaction():
        Entry.create(account=debit, amount=-amount, reference=ref)
        Entry.create(account=credit, amount=amount, reference=ref)
```

- Idempotent payment webhooks keyed on the provider reference
- Payouts queued and retried with backoff, never fired twice
- Daily reconciliation report comparing the ledger with the payment provider

## Outcome

Support tickets about missing money stopped. Finance could close the month from one report instead of three spreadsheets.', true, true, 2);
insert into public.projects (slug, title, summary, role, client, year, tags, stack, links, metrics, cover, gallery, body, featured, published, sort_order) values ('revenue-insights', 'Revenue Insights', 'A reporting layer that replaced five weekly spreadsheets with one dashboard the leadership team trusts.', 'Data and BI engineer', 'Logistics company, Lagos', 2024, array['Data', 'BI']::text[], array['SQL', 'Python', 'PostgreSQL', 'Metabase']::text[], '[]'::jsonb, '[{"value":"5 to 1","label":"weekly reports consolidated"},{"value":"Daily","label":"refresh, previously weekly"}]'::jsonb, '{"src":"https://images.unsplash.com/photo-1551288049-bebda4e38f71","width":4810,"height":3207,"alt":"Analytics dashboard with revenue charts","credit":"Unsplash"}'::jsonb, '[{"src":"https://images.unsplash.com/photo-1526628953301-3e589a6a8b74","width":2947,"height":2121,"alt":"Dashboard tiles with key metrics","credit":"Unsplash"},{"src":"https://images.unsplash.com/photo-1543286386-713bdd548da4","width":5472,"height":3648,"alt":"A hand-drawn growth chart on paper","credit":"Unsplash"}]'::jsonb, '## The problem

Every Monday, three people spent half a day merging exports into spreadsheets. By the time leadership saw the numbers they were a week old, and nobody agreed on what "revenue" meant.

## What I built

- A small warehouse in PostgreSQL fed nightly from the operations database and the accounting tool
- A shared set of metric definitions, written down and reviewed with finance before any chart was built
- A dashboard per audience: leadership, operations and sales, each answering the questions that team actually asks

## Decisions worth noting

The hard part was not the tooling. It was agreeing on definitions. I ran two short workshops to settle what counts as a delivered order and when revenue is recognised, then encoded those rules in SQL views so every chart uses the same logic.

## Outcome

The Monday spreadsheet ritual ended, and the weekly leadership meeting now starts from the dashboard.', true, true, 3);
insert into public.projects (slug, title, summary, role, client, year, tags, stack, links, metrics, cover, gallery, body, featured, published, sort_order) values ('chatcommerce', 'ChatCommerce', 'Selling inside WhatsApp: catalogue, cart and payment links in a chat thread, with an AI assistant answering product questions.', 'Full-stack engineer', 'Own product', 2026, array['AI', 'Commerce']::text[], array['TypeScript', 'Node.js', 'WhatsApp Cloud API', 'Claude', 'PostgreSQL']::text[], '[{"label":"Source","url":"https://github.com/zeddyemy/ChatCommerce"}]'::jsonb, '[]'::jsonb, '{"src":"https://images.unsplash.com/photo-1563986768609-322da13575f3","width":6720,"height":4480,"alt":"Testing a web app on a laptop and a phone","credit":"Unsplash"}'::jsonb, '[{"src":"https://images.unsplash.com/photo-1677442136019-21780ecad995","width":5120,"height":2880,"alt":"Abstract render of an AI processor","credit":"Unsplash"}]'::jsonb, '## The problem

Many small sellers already run their business on WhatsApp. They lose sales answering the same questions late at night and copying prices by hand.

## What I built

A WhatsApp assistant connected to the seller''s catalogue. It answers product questions from real stock data, builds a cart in the conversation and sends a payment link. When it is not sure, it hands the chat to a human.

