insert into public.projects (slug, title, summary, role, client, year, tags, stack, links, metrics, cover, gallery, body, featured, published, sort_order) values ('kyb-verification', 'KYB Verification', 'Business verification inside a merchant onboarding flow, integrating a third-party KYB API into a Laravel app.', 'Backend engineer', 'Fintech client', 2024, array['Fintech', 'Integrations']::text[], array['PHP', 'Laravel', 'MySQL', 'YouVerify API']::text[], '[{"label":"Source","url":"https://github.com/zeddyemy/kyb"}]'::jsonb, '[]'::jsonb, '{"src":"https://images.unsplash.com/photo-1544197150-b99a580bb7a8","width":6000,"height":4000,"alt":"Patch panel with blue network cables","credit":"Unsplash"}'::jsonb, '[]'::jsonb, '## The problem

